import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
        except StopIteration:
            break

        matrix = []
        for r in range(N):
            row = []
            for c in range(N):
                row.append(int(next(iterator)))
            matrix.append(row)

        ops = 0
        current_transpose_count = 0

        for L in range(N, 0, -1):
            target_row = L - 1
            target_col = L - 1

            val_at_target = matrix[target_row][target_col]
            expected_val = (target_row * N) + (target_col + 1)

            if val_at_target != expected_val:
                ops += 1
                current_transpose_count += 1

                temp_matrix = [row[:] for row in matrix]
                for i in range(L):
                    for j in range(L):
                        temp_matrix[i][j] = matrix[j][i]
                matrix = temp_matrix

        results.append(str(ops))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
